  "catalogue": {
    "name": "Shopify.Order.CreateSalesDocument",
    "isEnabled": true,
    "filterTableNo": 30118,
    "description": "Creates the Business Central sales order or invoice of an imported Shopify order.",
    "selectionDescription": "Use for an already imported Shopify order that has no Business Central document yet. It does not import orders from Shopify, does not release or post the document beyond the shop's own setting, and does not create refunds.",
    "messageDirection": "Inbound",
    "keywords": [
      "shopify order",
      "create sales order",
      "create sales invoice",
      "process shopify order",
      "convert shopify order"
    ],
    "chargeable": true
  },
  "chapters": {
    "target": [
      {
        "source": "Shpfy Order Header",
        "form": "data.orderId",
        "description": "The Shopify Order Id of an imported order (table 30118)."
      }
    ],
    "parameters": [
      {
        "name": "orderId",
        "type": "integer",
        "required": true,
        "description": "The Shopify Order Id of an imported order, e.g. from Data.Records.Get on table 30118."
      }
    ],
    "response": {
      "contentType": "text/json",
      "fields": [
        {
          "name": "status",
          "type": "string",
          "description": "Success."
        },
        {
          "name": "orderId",
          "type": "integer",
          "description": "The Shopify Order Id."
        },
        {
          "name": "documentType",
          "type": "string",
          "description": "Order or Invoice, following the shop's Create Invoices From Orders setting."
        },
        {
          "name": "documentNo",
          "type": "string",
          "description": "The No. of the created sales document."
        },
        {
          "name": "code",
          "type": "string",
          "description": "Present on errors only. The application error code, or BusinessCentralError when no code was supplied."
        }
      ]
    },
    "errors": [
      {
        "code": "MissingParameter",
        "error": "Parameter \"orderId\" is required.",
        "when": "The request has no orderId. Nothing was changed.",
        "fix": "Send data.orderId with the Shopify Order Id."
      },
      {
        "code": "InvalidParameterFormat",
        "error": "Parameter \"orderId\" must be a whole number greater than 0.",
        "when": "The value is not a positive integer. Nothing was changed.",
        "fix": "Send the Shopify Order Id as a number."
      },
      {
        "code": "RecordNotFound",
        "error": "Shopify order {id} was not found.",
        "when": "No imported order has this Id. Nothing was changed.",
        "fix": "Import the order first, or read table 30118 with Data.Records.Get."
      },
